 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Detect horizontal/vertical frame lines: mostly one separator color,
    # periodically interrupted by colored junction markers.
    colors = {}
    for r in range(h):
        vals = [v for v in grid[r] if v != 8]
        if vals and len(vals) >= w * 0.8:
            colors[r] = vals
    row_lines = list(colors)
    # The frame spacing is the smallest repeated interval among frame rows.
    def period(lines):
        ds = [b-a for a,b in zip(lines, lines[1:]) if b>a]
        if not ds: return len(lines) or 1
        from math import gcd
        p=ds[0]
        for d in ds[1:]: p=gcd(p,d)
        return p
    pr = period(row_lines)
    rr = list(range(row_lines[0], h, pr)) if row_lines else list(range(h))
    # Vertical lattice lines are dominated by separator color 5, while 8 fills tiles.
    cands=[]
    for c in range(w):
        vals=[grid[r][c] for r in range(h)]
        if sum(v != 8 for v in vals) >= h*0.8: cands.append(c)
    pc=period(cands)
    cc=list(range(cands[0],w,pc)) if cands else list(range(w))
    # Convert ordinary frame intersections to the interior tile color.
    fill=max(set(v for row in grid for v in row), key=lambda x:sum(row.count(x) for row in grid))
    out=[[fill if grid[r][c] != fill and grid[r][c] in (5,4,3,6,7) else grid[r][c] for c in cc] for r in rr]
    # Remove repeated adjacent bands and columns.
    compact=[]
    for row in out:
        if not compact or row != compact[-1]: compact.append(row)
    keep=[]
    for j in range(len(compact[0])):
        if not keep or any(row[j] != row[keep[-1]] for row in compact): keep.append(j)
    return [[row[j] for j in keep] for row in compact]
"
